typedef float rational_t;
typedef unsigned long uint64;

#define PSTRING_PCHUNK_NUMBER 4

class pstring
{
private:
  uint64 pchunk[PSTRING_PCHUNK_NUMBER];
  void pack_string(const char *the_string);
public:
  pstring(const char *target_string)
  {
    pack_string(target_string);
  }

  bool operator == (const pstring &check_me) const
  {
    for (unsigned i=0; i<PSTRING_PCHUNK_NUMBER; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }
};

class vector3d;
class stringx;
class generic_interface
{
public:
  virtual ~generic_interface() {}
  virtual bool get_ifc_num(const pstring &att, rational_t &val) { return(false); }
  virtual bool set_ifc_num(const pstring &att, rational_t val) { return(false); }
  virtual bool get_ifc_vec(const pstring &att, vector3d &val) { return(false); }
  virtual bool set_ifc_vec(const pstring &att, const vector3d &val) { return(false); }
  virtual bool get_ifc_str(const pstring &att, stringx &val) { return(false); }
  virtual bool set_ifc_str(const pstring &att, const stringx &val) { return(false); }
};

class entity;
class entity_interface : public generic_interface
{
protected:
  entity *my_entity;
};

typedef enum
{
  _TIME_WORLD = 0,
  _TIME_ABSOLUTE = 1,
  _TIME_RELATIVE = 2
} eTimeMode;

class time_interface : public entity_interface
{
protected:
  rational_t time_dilation;
  eTimeMode time_mode;
public:
  virtual bool get_ifc_num(const pstring &att, rational_t &val);
};

bool time_interface::get_ifc_num(const pstring &att, rational_t &val)
{
  { static pstring pstring_get("TIME_DILATION"); if(att == pstring_get) { val = time_dilation; return(true); } }
  { static pstring pstring_get("TIME_MODE"); if(att == pstring_get) { val = time_mode; return(true); } }

  return(false);
}
